/**
 * Private Email product logo: the Inboxies paper plane (the master mark in
 * `design/logo/inboxies-mark.svg`, small-size stroke weight) with a half-filled shield
 * badge at the bottom right. One colour (the current text colour), on a 32-unit grid so
 * it stays legible at 14–40 px. The paths are generated by
 * `scripts/generate-logo-assets.mjs`; re-run it instead of editing them.
 */
export default function PrivateEmailLogo({
	size = 20,
	className = "",
	showTile = false,
	alwaysLight = false,
}: {
	size?: number;
	className?: string;
	showTile?: boolean;
	alwaysLight?: boolean;
}) {
	const markSize = showTile ? Math.round(size * 0.8) : size;
	const svgContent = (
		<svg
			width={markSize}
			height={markSize}
			viewBox="0 0 32 32"
			className={showTile ? "" : className}
			fill="none"
			stroke="currentColor"
			strokeLinejoin="round"
			strokeLinecap="round"
			xmlns="http://www.w3.org/2000/svg"
			style={alwaysLight ? { color: "#1F1F24" } : undefined}
			aria-hidden="true"
		>
			{/* logo:generated:private */}
			<path d="M 1.62 9.48 L 22.18 1.64 A 1.89 1.89 0 0 1 24.59 4.13 L 16.6 23.29 A 1.22 1.22 0 0 1 14.69 23.76 L 10.69 20.39 L 8.2 23.56 A 0.97 0.97 0 0 1 6.48 23.12 L 5.1 15.21 L 1.21 11.43 A 1.18 1.18 0 0 1 1.62 9.48 Z" strokeWidth={1.371} />
			<path d="M 0.86 10.56 L 2.72 10.76 L 11.95 10.73 L 23.64 2.62 M 23.64 2.62 L 8.71 16.92 L 8.22 17.72 L 7.76 19.9 M 13.83 11.97 L 15.36 21.95 L 15.68 24.03 M 23.64 2.62 L 24.19 2.07" strokeWidth={1.143} />
			<path d="M 8.5 18.59 L 9.62 17.44 L 10.3 17.66 L 13.96 21.26 L 13.97 21.9 L 13.36 22.51 L 10.69 20.39 L 8.2 23.56 A 0.97 0.97 0 0 1 7.29 23.92 Z" fill="currentColor" />
			<path d="M 24.8 17.28 L 29.76 19.2 V 23.52 C 29.76 26.72 27.68 28.96 24.8 30.24 C 21.92 28.96 19.84 26.72 19.84 23.52 V 19.2 Z" strokeWidth={1.166} />
			<path d="M 24.8 17.28 L 29.76 19.2 V 23.52 C 29.76 26.72 27.68 28.96 24.8 30.24 Z" fill="currentColor" strokeWidth={1.166} />
			{/* /logo:generated:private */}
		</svg>
	);

	if (showTile) {
		return (
			<div
				className={`inline-flex items-center justify-center overflow-hidden ${
					alwaysLight
						? "bg-white border border-gray-200 shadow-sm"
						: "bg-kumo-base border border-kumo-line shadow-sm"
				} ${className}`}
				style={{ width: size, height: size, borderRadius: size * 0.22 }}
			>
				{svgContent}
			</div>
		);
	}

	return svgContent;
}
